async function send(api, method, path, opts) {
  let res;
  for (let attempt = 1; attempt <= 5; attempt++) {
    res = await api.request(method, path, opts);
    if (res.status === 429) {
      if (attempt < 5) await api.sleep(Number(res.headers["retry-after"]) * 1000);
      continue;
    }
    if (res.status >= 500) {
      if (attempt < 5) await api.sleep(200 * 2 ** (attempt - 1));
      continue;
    }
    return res;
  }
  return res; // still 429/5xx after 5 attempts
}

async function listAllCustomerIds(api) {
  const ids = [];
  let cursor;
  while (true) {
    const query = { limit: 100 };
    if (cursor !== undefined) query.starting_after = cursor;
    const res = await send(api, "GET", "/v1/customers", { query });
    if (res.status !== 200) throw new Error("GET /v1/customers failed with status " + res.status);
    const { data, has_more } = res.body;
    for (const c of data) ids.push(c.id);
    if (!has_more || data.length === 0) break;
    cursor = data[data.length - 1].id;
  }
  return ids;
}

