function parseSignature(header) {
  if (typeof header !== "string" || header.length === 0) return null;
  let t = null;
  const v1 = [];
  for (const part of header.split(",")) {
    const i = part.indexOf("=");
    if (i <= 0) return null;
    const k = part.slice(0, i).trim();
    const v = part.slice(i + 1).trim();
    if (k === "t") t = v;
    else if (k === "v1") v1.push(v);
  }
  if (t === null || !/^\d+$/.test(t) || v1.length === 0) return null;
  return { t, v1 };
}

function safeEqual(a, b) {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

async function handleWebhooks(api, deliveries, secret) {
  const seen = new Set();
  const out = [];
  for (const d of deliveries) {
    const sig = parseSignature(d.header);
    if (!sig) { out.push("malformed"); continue; }
    const expected = api.hash(secret + "." + sig.t + "." + d.payload);
    if (!sig.v1.some((s) => safeEqual(s, expected))) { out.push("invalid_signature"); continue; }
    if (Math.abs(api.now() / 1000 - Number(sig.t)) > 300) { out.push("stale"); continue; }
    let event;
    try { event = JSON.parse(d.payload); } catch (e) { out.push("malformed"); continue; }
    if (seen.has(event.id)) { out.push("duplicate"); continue; }
    seen.add(event.id);
    const res = await send(api, "POST", "/v1/fulfillments", { body: { event_id: event.id, type: event.type } });
    if (res.status !== 200) throw new Error("fulfillment failed: " + res.status);
    out.push("processed");
  }
  return out;
}

