async function listAll(api, path, baseQuery) {
  const out = [];
  let cursor;
  while (true) {
    const query = Object.assign({ limit: 100 }, baseQuery);
    if (cursor !== undefined) query.starting_after = cursor;
    const res = await send(api, "GET", path, { query });
    if (res.status !== 200) throw new Error("GET " + path + " failed: " + res.status);
    out.push(...res.body.data);
    if (!res.body.has_more || res.body.data.length === 0) return out;
    cursor = res.body.data[res.body.data.length - 1].id;
  }
}

async function reconcilePayouts(api) {
  const mismatches = [];
  const payouts = await listAll(api, "/v1/payouts", {});
  for (const p of payouts) {
    if (p.status !== "paid") continue;
    const txns = await listAll(api, "/v1/balance_transactions", { payout: p.id });
    const actual = txns.reduce((sum, t) => sum + (t.amount - t.fee), 0);
    if (actual !== p.amount) mismatches.push({ payout: p.id, expected: p.amount, actual, diff: actual - p.amount });
  }
  return mismatches;
}

