async function runReport(api, timeoutMs) {
  const start = api.now();
  const created = await send(api, "POST", "/v1/reports", { body: { type: "balance" } });
  if (created.status !== 200) throw new Error("could not create report: " + created.status);
  const id = created.body.id;
  let delay = 500;
  while (true) {
    const res = await send(api, "GET", "/v1/reports/" + id);
    if (res.status !== 200) throw new Error("poll failed: " + res.status);
    const job = res.body;
    if (job.status === "succeeded") return { status: "succeeded", url: job.result_url };
    if (job.status === "failed") return { status: "failed", error: job.error_code };
    const remaining = start + timeoutMs - api.now();
    if (remaining <= 0) return { status: "timeout" };
    await api.sleep(Math.min(delay, remaining));
    delay = Math.min(delay * 2, 8000);
  }
}
